<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $tables = DB::select("SELECT tablename FROM pg_tables WHERE schemaname = 'public' AND tablename LIKE 'category_data_%'"); foreach ($tables as $t) { $tableName = $t->tablename; Schema::table($tableName, function (Illuminate\Database\Schema\Blueprint $t) { if (!Schema::hasColumn($t->getTable(), "added_by_user_id")) { $t->unsignedBigInteger("added_by_user_id")->nullable(); } if (!Schema::hasColumn($t->getTable(), "is_approved")) { $t->boolean("is_approved")->default(true); } if (!Schema::hasColumn($t->getTable(), "coordinate_mismatch")) { $t->boolean("coordinate_mismatch")->default(false); } if (!Schema::hasColumn($t->getTable(), "is_update_proposal")) { $t->boolean("is_update_proposal")->default(false); } }); echo "Migrated $tableName\n"; }
